import {createCompassController,directionName} from './sensor-compass.mjs';
import {FESTIVAL_THEMES,festivalInfo} from './festivals.mjs';
import {ELEMENTS,IDENTITIES,SIGN_TYPES,dateKey,dateParts,dayInfo,dailyDirections,chartFor,randomIndex,parseOptions,landing,pointer,stable,category,modern,identityTask,dailySign,defaultState,validateState,groupTerms,wheelProgress,migrateState} from './core.mjs';
const KEY='almanac-youth-web-v1';
const native=globalThis.AlmanacNative||null;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const terms=await fetch('./terms.json').then(r=>{if(!r.ok)throw Error('术语资源读取失败');return r.json();});
let storageIssue='',blocked=false;
let state;try{const local=localStorage.getItem(KEY);let raw=local;if(native){const fromNative=native.readState(),remote=JSON.parse(fromNative);if(!local||(remote.updatedAt||0)>=(JSON.parse(local).updatedAt||0))raw=fromNative;}state=raw?migrateState(JSON.parse(raw)):defaultState();}catch(error){state=defaultState();storageIssue='本机资料读取失败，原内容已保留，暂不覆盖保存。可先导出原资料或在设置中明确重置。';blocked=true;}
const ui={tab:0,part:0,compassMode:0,direction:'cai',festivalPreview:'',date:dateKey(),filter:'全部',type:0,rotation:0,result:'',spinning:false,signBusy:false,offline:false};
const e=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let compassPaintFrame=0;
const liveCompass=createCompassController(window,()=>{if(!compassPaintFrame)compassPaintFrame=requestAnimationFrame(()=>{compassPaintFrame=0;paintCompass();});});
function paintCompass(){const status=document.querySelector('#compass-live-status');if(!status)return;const c=liveCompass.snapshot(),heading=document.querySelector('#compass-heading'),source=document.querySelector('#compass-source'),button=document.querySelector('[data-action="compass-toggle"]'),rotor=document.querySelector('.compass-rotor');if(status.textContent!==c.message)status.textContent=c.message;status.dataset.status=c.status;heading.textContent=c.heading===null?'—°':Math.round(c.heading)%360+'° · '+directionName(c.heading);source.textContent=c.heading===null?'固定图 · 尚未取得实时北向':c.source+(c.accuracy===null?'':' · 设备精度 ±'+Math.round(c.accuracy)+'°');button.textContent=c.active?'停用实时罗盘':'启用实时罗盘';button.disabled=c.status==='requesting';button.setAttribute('aria-pressed',String(c.active));rotor.setAttribute('transform','rotate('+(-c.angle)+' 180 180)');document.querySelector('.compass-frame').classList.toggle('tracking',c.status==='live');}
const gold='#d8b779';let toastTimer;let posterURL=null,posterFile=null;
function save(){if(blocked){toast(storageIssue);return false;}try{state.updatedAt=Date.now();const raw=JSON.stringify(state);localStorage.setItem(KEY,raw);if(native&&!native.saveState(raw)){storageIssue='本机网页资料已保存，但原生组件同步失败，请导出备份后重试。';toast(storageIssue);return false;}return true;}catch(error){storageIssue='当前浏览器无法保存资料，请检查私密浏览或存储空间；本次修改尚未持久保存。';toast(storageIssue);return false;}}
function toast(text){const box=document.querySelector('#toast');box.textContent=text;box.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.style.display='none',3600);}
function card(title,body,extra=''){return `<section class="card ${extra}"><h2 class="card-title">${title}</h2>${body}</section>`;}
function foldCard(title,body){return `<details class="card compact-details"><summary>${title}<span>展开</span></summary>${body}</details>`;}
function btn(text,action,cls='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function modal(title,body){dialog.innerHTML=`<h2 id="modal-title">${e(title)}</h2>${body}`;if(!dialog.open)dialog.showModal();}
function closeModal(){if(dialog.open)dialog.close();}
function closeButton(){return btn('关闭','close','full');}
function idName(){return state.identity===5?(state.role||'我的身份'):IDENTITIES[state.identity];}
function task(){return identityTask(state.identity,state.goal,dateKey(),state.id);}
function profileChart(){try{return state.profile?chartFor(state.profile):null;}catch{return null;}}
function hero(info=dayInfo(ui.date)){const b=profileChart();return card(`<span>${e(info.date)} · ${e(info.weekday)}</span><small>${e(info.jieqi||'知时而行')}</small>`,`<div class="hero-main"><div class="day-number">${String(info.day).padStart(2,'0')}</div><div class="grow"><h2>${e(info.lunar)}</h2><p>${info.year} 年 ${info.month} 月 · 传统历法</p></div><div class="hero-seal">${e(b?.master||'黄历')}</div></div><div class="pillars-line"><span>${e(info.yearPillar)}年</span><span>${e(info.monthPillar)}月</span><span>${e(info.dayPillar)}日</span></div>`,'hero');}
function yiCard(info,brief=false){const columns=[info.yi,info.ji].map((items,g)=>{const words=items.filter(w=>brief||ui.filter==='全部'||category(w)===ui.filter);let groups=state.traditional&&!brief?words.map(word=>({word,words:[word],label:word})):groupTerms(words,terms,state.style);if(brief)groups=groups.slice(0,2);return `<div class="yi-column ${g?'negative':'positive'}"><h3>${g?'忌 · 放慢一点':'宜 · 可以安排'}</h3>${groups.map(item=>`<button class="term-button" data-action="term-group" data-words="${e(JSON.stringify(item.words))}" data-avoid="${g}"><span>${e(item.label)}${item.words.some(w=>['求医','治病','求医疗病'].includes(w))?'〔诊疗请及时就医〕':''}</span><small>ⓘ</small></button>`).join('')||'<p class="tiny">本分类暂无事项</p>'}</div>`;}).join('');return card(brief?(info.date===dateKey()?'今日宜忌':'所选日期宜忌'):'当日宜忌 · 点击看原义',`<div class="yi-columns">${columns}</div><p class="tiny yi-note">传统黄历 · 年轻化改编，非现实预测</p>`,'yi-card');}
function home(){const info=dayInfo(ui.date),festival=festivalInfo(ui.date);return `<div class="calendar-home">${festivalBanner()}${monthGrid()}<section class="selected-day" aria-live="polite"><div><span class="eyebrow">${ui.date===dateKey()?'今天':'已选日期'} · ${e(info.weekday)}</span><h2>${info.month}月${info.day}日 <small>${e(info.lunar)}</small></h2><p>${e([info.jieqi,...festival.names].filter(Boolean).join(' · ')||'平常日，也值得认真过')}</p><div class="tiny">${e(info.yearPillar)}年 · ${e(info.monthPillar)}月 · ${e(info.dayPillar)}日</div></div>${btn('查看黄历 ↗','nav','outline','data-tab="1"')}</section>${yiCard(info,true)}<div class="mouth-line"><span>今日嘴替</span><strong>${e(dailyQuote())}</strong></div><div class="quick-pair"><button class="quick" data-action="open-wheel">${icon(2)}<span>随机转盘<small>给小纠结一个答案</small></span></button><button class="quick" data-action="nav" data-tab="3">${icon(3)}<span>今日抽签<small>留一点小期待</small></span></button></div><details class="card theme-compact"><summary><div><span class="tiny">${e(idName())} · 今日小建议</span><p>${e(task())}</p></div><strong>${60+stable(dateKey()+state.id+idName(),40)}<small>娱乐分</small></strong></summary><p class="tiny">趣味评分，非现实预测。幸运色：${['鎏金','暖白','黛青','朱红','竹绿'][stable(dateKey()+state.id,5)]} · 幸运数字 ${1+stable(dateKey()+state.id+'num',9)}</p><div class="row">${btn('切换身份','identity')}${btn('主题海报','share-theme')}</div></details><div class="row">${btn('分享所选黄历','share-day')}${btn('节日主题预览','festival-preview')}</div></div>`;}
function dailyQuote(){return [['先把自己照顾好，再忙别的。','今天的电量，留一点给自己。','先做一小步，别等满状态。','有空见面，没空好好吃饭。'],['先别焦虑，饭吃了吗？','今天先不卷，先把事做完。','生活偶尔卡顿，重启试试。','我的好运：文件记得保存。'],['把日常过细，把心事放轻。','今天有序，也留一点闲。','不赶每一阵风，走自己的路。','把喜欢的事，放进今天。']][state.style][stable(dateKey(),4)];}
function festivalBanner(){const actual=festivalInfo(ui.date).theme,t=FESTIVAL_THEMES.find(t=>t.id===ui.festivalPreview)||actual;if(!t)return '';return `<aside class="festival-banner" style="--festival-gold:${t.colors[0]};--festival-bg:${t.colors[1]}"><span class="festival-seal" aria-hidden="true">${t.mark}</span><div><span class="eyebrow">${ui.festivalPreview?'主题预览 · 非当前节日':t.name}</span><strong>${t.title}</strong><p>${t.description}</p></div>${btn(ui.festivalPreview?'退出预览':'更多主题',ui.festivalPreview?'festival-reset':'festival-preview','text-btn')}</aside>`;}
function festivalPreview(){modal('节日限定 · 主题预览',`<p class="tiny">只切换节日展示，不改变所选日期、黄历或抽签结果。节日当天自动展示对应主题。</p><div class="festival-options">${FESTIVAL_THEMES.map(t=>`<button data-action="festival-set" data-id="${t.id}" style="--festival-bg:${t.colors[1]};--festival-gold:${t.colors[0]}"><b>${t.mark}</b><span>${t.name}<small>${t.title}</small></span></button>`).join('')}</div>${btn('恢复日期自动主题','festival-reset','full')}${closeButton()}`);}

function monthGrid(){const [y,m,day]=dateParts(ui.date),first=new Date(y,m-1,1,12),offset=(first.getDay()+6)%7,count=new Date(y,m,0).getDate();let cells=['一','二','三','四','五','六','日'].map((w,i)=>`<div class="weekday ${i>4?'weekend':''}">${w}</div>`).join('');cells+='<div aria-hidden="true"></div>'.repeat(offset);for(let d=1;d<=count;d++){const key=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,l=Solar.fromYmd(y,m,d).getLunar(),f=festivalInfo(key),qi=l.getJieQi(),holiday=f.names[0],sub=qi||holiday||(l.getDay()===1?l.getMonthInChinese()+'月':l.getDayInChinese());cells+=`<button class="date-cell ${d===day?'selected':''} ${key===dateKey()?'today':''} ${qi||holiday?'festival-date':''}" data-action="select-date" data-date="${key}" aria-label="${key} 农历${l.getMonthInChinese()}月${l.getDayInChinese()} ${e([qi,...f.names].filter(Boolean).join(' '))}" ${d===day?'aria-pressed="true"':'aria-pressed="false"'}><span>${d}</span><small>${e(sub)}</small>${key===dateKey()?'<i aria-hidden="true"></i>':''}</button>`;}return `<section class="card month-card" aria-label="完整月历"><div class="month-toolbar"><div><span class="eyebrow">${y} / MONTH</span><h2>${m}<small>月</small></h2></div><div class="month-tools">${btn('‹','month-prev','icon-btn','aria-label="上个月"')}${btn('今天','today','today-btn')}${btn('›','month-next','icon-btn','aria-label="下个月"')}</div></div><label class="month-jump">跳转日期<input id="query-date" aria-label="跳转日期" type="date" value="${ui.date}" min="1900-01-01" max="2100-12-31"></label><div class="calendar-grid">${cells}</div><p class="calendar-legend"><span>● 今天</span><span>金字 · 节气 / 节日</span><span>点击日期看当天黄历</span></p></section>`;}

function directionPanel(d){return `<section class="card daily-directions"><div class="directions-heading"><div><span class="eyebrow">${d.date===dateKey()?'今日吉位':'所选日吉位'} · 传统黄历</span><h2>${e(d.pillar)}日 <small>五神方位</small></h2></div><label>查询日期<input id="query-date" aria-label="吉位查询日期" type="date" value="${e(d.date)}" min="1900-01-01" max="2100-12-31"></label></div><div class="direction-chips">${d.items.map(x=>`<button data-action="choose-direction" data-id="${x.id}" class="direction-chip ${ui.direction===x.id?'selected':''}" aria-pressed="${ui.direction===x.id}"><span>${x.name}</span><strong>${x.direction}</strong><small>${x.gua} · ${x.bearing}°</small></button>`).join('')}</div><p class="tiny">${e(d.clash)} · 煞${e(d.sha)} <button class="text-btn" data-action="direction-help">方位怎么看？</button></p><p class="tiny">点击吉神可在盘面标记方位。按所选公历日期查询，与个人命盘无关。</p></section>`;}
function compass(){const auspicious=dailyDirections(ui.date),chosen=auspicious.items.find(x=>x.id===ui.direction)||auspicious.items[1],rad=(chosen.bearing-90)*Math.PI/180;const marker=`<g class="auspicious-marker"><line x1="180" y1="180" x2="${180+Math.cos(rad)*113}" y2="${180+Math.sin(rad)*113}" stroke="var(--gold)" stroke-width="2" stroke-dasharray="4 4"/><circle cx="${180+Math.cos(rad)*113}" cy="${180+Math.sin(rad)*113}" r="6" fill="var(--gold)"/></g>`;const words=['子','癸','丑','艮','寅','甲','卯','乙','辰','巽','巳','丙','午','丁','未','坤','申','庚','酉','辛','戌','乾','亥','壬'];let ticks='';for(let i=0;i<72;i++){const a=(i*5-90)*Math.PI/180,r1=i%3?164:159;ticks+=`<line x1="${180+Math.cos(a)*r1}" y1="${180+Math.sin(a)*r1}" x2="${180+Math.cos(a)*170}" y2="${180+Math.sin(a)*170}" stroke="var(--line)"/>`;}const texts=words.map((w,i)=>{const a=(i*15-90)*Math.PI/180;return `<g class="mountain" role="button" tabindex="0" data-action="mountain" data-index="${i}" aria-label="${w} ${i*15}度"><circle cx="${180+Math.cos(a)*141}" cy="${180+Math.sin(a)*141}" r="14" fill="transparent"/><text x="${180+Math.cos(a)*141}" y="${185+Math.sin(a)*141}" text-anchor="middle" font-size="17">${w}</text></g>`;}).join('');const dirs=['北','东北','东','东南','南','西南','西','西北'].map((w,i)=>{const a=(i*45-90)*Math.PI/180;return `<text x="${180+Math.cos(a)*95}" y="${185+Math.sin(a)*95}" text-anchor="middle" font-size="12" opacity=".65">${w}</text>`;}).join('');return directionPanel(auspicious)+card('二十四山 · 每日方位',`<div class="compass-live-hud"><div><strong id="compass-heading">—°</strong><small id="compass-source">固定图 · 尚未取得实时北向</small></div>${btn('启用实时罗盘','compass-toggle','primary','aria-pressed="false"')}</div><p id="compass-live-status" class="compass-status" role="status" aria-live="polite">固定方位图 · 点击启用后读取手机方向</p><div class="compass-frame"><span class="compass-fixed-pointer" aria-hidden="true">▼</span><svg class="compass" viewBox="0 0 360 360" aria-label="传统方位盘，启用并获得真实方向后转动"><g class="compass-rotor">${ticks}${[170,122,74,48].map(r=>`<circle cx="180" cy="180" r="${r}" fill="none" stroke="var(--gold)" opacity=".5"/>`).join('')}${texts}${dirs}${marker}</g><text x="180" y="177" text-anchor="middle" font-size="22">戊 · 己</text><text x="180" y="198" text-anchor="middle" font-size="10" opacity=".65">中央属土</text></svg></div><p class="direction-focus">金色虚线：${e(chosen.name)} · ${e(chosen.direction)} ${chosen.bearing}°</p><p class="tiny" style="text-align:center">试用：请竖屏正向、屏幕朝上平放。未启用时上北下南。</p><details class="faq"><summary>授权、校准和精度说明</summary><p>iPhone请点击启用后允许方向访问；安卓需浏览器及手机提供绝对方向。无需定位，方向数据不上传、不保存。远离磁吸配件与金属，和系统指南针对照；未校正磁偏角。仅供方位体验，暂不支持横屏或大角度倾斜。</p></details><div class="short-rule"></div><p class="muted">十天干：甲乙丙丁戊己庚辛壬癸<br>十二地支：子丑寅卯辰巳午未申酉戌亥<br>外圈由八天干、十二地支与四隅卦组成，戊己居中。点击盘面查看方位解释。</p>`);}
function calendarPage(){const info=dayInfo(ui.date),f=festivalInfo(ui.date);return `<section class="card almanac-date"><div><span class="eyebrow">当日黄历</span><h2>${info.month}月${info.day}日 <small>${e(info.weekday)}</small></h2><p>${e(info.lunar)}${[info.jieqi,...f.names].filter(Boolean).map(x=>' · '+e(x)).join('')}</p></div><label class="date-picker"><span class="tiny">查询日期</span><input id="query-date" type="date" value="${ui.date}" min="1900-01-01" max="2100-12-31"></label></section><div class="almanac-controls">${btn(state.traditional?'传统版 ⇄':'人话版 ⇄','language')}<select id="category" aria-label="生活分类">${['全部','恋爱','工作','学习','社交','居家','出行','传统习俗'].map(x=>`<option ${x===ui.filter?'selected':''}>${x}</option>`).join('')}</select>${btn('今天','today')}</div>${yiCard(info)}<div class="card pillar-summary"><span>${e(info.yearPillar)}年 · ${e(info.monthPillar)}月 · ${e(info.dayPillar)}日</span><p class="tiny">${e(info.clash)} · 民俗参考</p></div><details class="card compact-details"><summary>传统习俗择日 <span>搬家 / 婚礼 / 开业</span></summary><p class="tiny">从所选日期起查60天，匹配公共黄历宜且非忌；不是个人八字择日。</p><div class="row">${['入宅','嫁娶','开市'].map((w,i)=>btn(['搬家','婚礼','开业'][i],'find-dates','',`data-word="${w}"`)).join('')}</div></details><div class="row">${btn('分享这一天','share-day','primary')}${btn('查看完整月历','nav','','data-tab="0"')}</div>`;}
function compassPage(){return `<div class="section-nav mode-switch" aria-label="罗盘模式">${['方位罗盘','随机转盘'].map((v,i)=>`<button data-action="compass-mode" data-mode="${i}" class="${ui.compassMode===i?'active':''}" aria-pressed="${ui.compassMode===i}">${v}</button>`).join('')}</div>${ui.compassMode===0?`<div class="compass-intro"><span class="eyebrow">ORIENTATION / 二十四山</span><h2>知方位，也知进退</h2></div>${compass()}`:wheelPage()}`;}

function wheelSVG(){const n=state.options.length,sweep=360/n,r=140,c=160;const point=a=>[c+Math.cos((a-90)*Math.PI/180)*r,c+Math.sin((a-90)*Math.PI/180)*r];let body='';for(let i=0;i<n;i++){const a=point(i*sweep),b=point((i+1)*sweep),mid=(i+.5)*sweep-90;body+=`<path d="M ${c},${c} L ${a} A ${r},${r} 0 ${sweep>180?1:0},1 ${b} Z" fill="${['#27272f','#50422e','#202e32','#3b2d33'][i%4]}" stroke="#ad8f55" stroke-width=".7"/><text x="${c+Math.cos(mid*Math.PI/180)*94}" y="${c+Math.sin(mid*Math.PI/180)*94+4}" text-anchor="middle" fill="#efe3c9" font-size="12">${e([...state.options[i]].slice(0,7).join(''))}</text>`;}return `<svg viewBox="0 0 320 320" class="wheel-disc" id="wheel-disc" style="transform:rotate(${ui.rotation}deg)" aria-hidden="true">${body}</svg>`;}
function wheelPage(){return `<div class="two-column"><div>${card('把纠结交给转盘',`<p class="tiny">每项等概率 · 顶部金色指针指示结果</p><div class="wheel-box"><div class="wheel-pointer"></div>${wheelSVG()}<button class="wheel-center" data-action="spin" aria-label="转盘中央开始按钮"><b>GO</b><small>开始</small></button></div><div class="result" id="wheel-result" aria-live="polite">${ui.spinning?'转动中…':ui.result?'抽中：'+e(ui.result):'转一个日常小决定'}</div>${btn(ui.spinning?'转动中…':'开始旋转','spin','primary full',ui.spinning?'disabled':'')}${btn('编辑选项标签','edit-options','full')}${ui.result?btn('分享本次结果图片','share-wheel','full'):''}`)}</div><div>${card('预设模板',`<div class="quick-grid" style="grid-template-columns:repeat(2,1fr)">${['今天吃什么','去哪玩','谁请客','先做什么'].map((v,i)=>`<button class="quick" data-action="template" data-template="${i}">${v}</button>`).join('')}</div>${btn('收藏当前转盘','save-wheel','full')}<p class="tiny">选项不会因生日或个人命盘改变概率。声音反馈请保持手机音量开启。</p><label class="check"><input type="checkbox" id="sound" ${state.sound?'checked':''}>旋转与结果音效</label><label class="check"><input type="checkbox" id="vibrate" ${state.vibrate?'checked':''}>结果震动（设备支持时）</label>${native?`<label class="check"><input type="checkbox" id="native-shake" ${state.shake?'checked':''}>摇一摇开始转盘</label>`:''}`)}${card('我的转盘收藏',state.wheels.length?state.wheels.map((w,i)=>`<div class="saved-row"><button class="text-btn grow" data-action="load-wheel" data-index="${i}">${e(w.name)}<small class="tiny"> · ${w.options.length}项</small></button><button class="text-btn" data-action="delete-wheel" data-index="${i}" aria-label="删除${e(w.name)}">删除</button></div>`).join(''):'<p class="muted">还没有收藏转盘。编辑后可以保存，随时再用。</p>')}</div></div>`;}
function recordFor(type=ui.type){return state.signs.find(x=>x.day===dateKey()&&x.type===type);}
function signPage(){const r=recordFor(),motif=['☁','☾','✦','◇','✧'][ui.type];return `<div class="section-nav">${SIGN_TYPES.map((v,i)=>`<button data-action="sign-type" data-type="${i}" class="${ui.type===i?'active':''}">${v}</button>`).join('')}</div><div class="narrow">${card(`${SIGN_TYPES[ui.type]} / ${dateKey()}`,`<div class="sign-stage ${ui.signBusy?'drawing':''}">${r&&!ui.signBusy?`<div class="sign-revealed"><span class="sign-motif" aria-hidden="true">${motif}</span><div class="sign-level">${e(r.grade)} <small>娱乐签</small></div><p class="sign-text">${e(r.text)}</p><p class="muted">今日小任务<br>${e(r.task)}</p><div class="sign-rule"></div><span class="tiny">生活的答案，由你书写</span></div>`:`<div class="sign-can ${ui.signBusy?'shaking':''}"><i></i><i></i><i></i><span>今日签</span></div><p class="muted" style="text-align:center">${ui.signBusy?'摇一摇，灵感正在路上…':'给今天留一点小期待'}</p>`}</div>${r&&!ui.signBusy?`<div class="row between">${btn(r.favorite?'★ 已收藏':'☆ 收藏','favorite')}${btn('分享签文海报','share-sign')}</div>`:''}${btn(ui.signBusy?'摇签中…':r?'重看今日签':'摇签 · 揭晓','draw','primary full',ui.signBusy?'disabled':'')}<p class="tiny">每日同类固定一支 · 寄语与等级仅供娱乐</p>`)}${btn('签文历史与收藏','history','full')}</div>`;}
function baziCard(b){return card('四柱八字 · 点击看解释',`<div class="bazi">${b.pillars.map((v,i)=>`<button class="column" data-action="pillar" data-index="${i}"><small>${['年柱','月柱','日柱','时柱'][i]}</small><strong>${e(v)}</strong><p>${e(b.wx[i]||'待补')}</p><small>${e(b.tenGods[i])}</small></button>`).join('')}</div>${!state.profile.known?'<p class="tiny">时分未知：未生成时柱和命宫。若恰逢节气交界日，年、月柱需补时分复核。</p>':''}`);}
function chartReading(b){if(state.reading===2)return `四柱：${b.pillars.join(' ')}。日主：${b.master}；年干十神：${b.tenGods[0]}；月干十神：${b.tenGods[1]}；日柱纳音：${b.nayin[2]}。`;const plain=`你的日主是${b.master}，指的是出生日的天干。四柱表示传统历法中的出生年、月、日、时，不是对人格好坏或人生结局的判定。`;return state.reading===1?plain+'年柱以立春、月柱按节气分界；纳音、命宫、胎元是不同的传统分类。五行图只统计干支表层字数，不能直接判断喜用神或强弱。':plain;}
function personalCardPreview(b){const info=dayInfo();return `<div class="hero card" style="margin-bottom:0"><div class="card-title">${state.privacy?'我的':e(state.profile?.name||'我的')} · 专属万年历</div><div class="hero-main"><div class="day-number" style="font-size:42px">${String(info.month).padStart(2,'0')} / ${String(info.day).padStart(2,'0')}</div><div class="hero-seal">${e(b?.master||'日历')}</div></div><p class="muted">${e(info.lunar)} · ${e(info.weekday)}</p>${b?`<div class="short-rule"></div><p style="color:var(--gold);font-family:serif;margin:7px 0">${e(b.pillars.join('　'))}</p>`:''}<p class="tiny" style="color:var(--gold)">宜 ${e(info.yi.slice(0,2).join(' · '))}</p><p class="tiny">忌 ${e(info.ji.slice(0,2).join(' · '))}</p></div>`;}
function myPage(){const b=profileChart();return `<div class="profile-heading"><span class="eyebrow">MY SPACE</span><h2>我的日历，自己定义</h2></div>${b?`${card(`${state.privacy?'我的':e(state.profile.name||'我的')} · 个人命格档案`,`<button class="text-btn" style="font-size:1.9rem" data-action="dict-term" data-word="日主">${e(b.master)}日主 ⓘ</button><p class="muted">${state.privacy?'出生资料已隐藏':e(state.profile.date)+' '+(state.profile.known?e(state.profile.time):'时分未知')+' · 北京时间'}</p><div class="row between">${btn(state.privacy?'显示资料':'隐藏资料','privacy')}${btn('修改出生资料','edit-profile')}${btn('删除档案','delete-profile','danger')}</div><label for="reading-select">解释深度</label><select id="reading-select">${['大白话','详细解读','专业术语'].map((v,i)=>`<option value="${i}" ${state.reading===i?'selected':''}>${v}</option>`).join('')}</select><p class="reading-summary">日主是传统八字的参照点。</p><details class="faq"><summary>展开当前层级解读</summary><p>${e(chartReading(b))}</p></details><div class="speech-controls">${btn('朗读','speak','',(native||'speechSynthesis'in window)?'':'disabled')}${btn('暂停','speech-pause','','disabled')}${btn('继续','speech-resume','','disabled')}${btn('停止','speech-stop','','disabled')}</div><p id="speech-status" class="tiny" aria-live="polite">朗读未开始</p>`)}<div class="two-column"><div>${baziCard(b)}${card('五行分布 · 表层字数',ELEMENTS.map((v,i)=>`<div class="wx-row"><span>${v}</span><div class="wx-track"><i style="width:${b.counts[i]/(state.profile.known?8:6)*100}%"></i></div><small>${b.counts[i]}/${state.profile.known?8:6}</small></div>`).join('')+'<p class="tiny">不含藏干权重；某项为0不等于命理的“缺”，不据此判断强弱或喜用神。</p>')}</div><div>${card('传统命格资料',`<button class="term-button" data-action="dict-term" data-word="纳音">日柱纳音：${e(b.nayin[2])} ⓘ</button><p>命宫：${e(b.ming)}</p><p>胎元：${e(b.tai)}</p><p class="tiny">传统分类仅供文化了解。胎元不代表真实受孕日期。</p>${btn('术语小词典','dictionary','full')}`)}${foldCard('你的个人命盘卡',`${personalCardPreview(b)}<p class="tiny">这是网页内的命盘卡，不是 iOS 系统桌面小组件。</p>`)}</div></div>`:card('以生日开启个人万年历',`<p class="quote">你的日主、四柱与五行图，从一个生日开始。</p><p class="muted">公历日期 + 北京时间。时分未知可以留空，资料只保存在本机。</p>${btn('＋ 建立我的命盘','edit-profile','primary full')}`)}${card('偏好设置',`<div class="settings-grid"><div><label for="identity-select">身份主题</label><select id="identity-select">${IDENTITIES.map((v,i)=>`<option value="${i}" ${state.identity===i?'selected':''}>${v}</option>`).join('')}</select></div>${state.identity===5?`${btn('编辑职业、兴趣和目标','custom-identity','full')}<p class="tiny">${e(state.role)} ${e(state.interest)} ${e(state.goal)}</p>`:''}<div class="settings-pair"><div class="grow"><label for="style-select">文案风格</label><select id="style-select">${['潮流版','整活版','轻奢版'].map((v,i)=>`<option value="${i}" ${state.style===i?'selected':''}>${v}</option>`).join('')}</select></div><div class="grow"><label for="theme-select">外观</label><select id="theme-select">${[['black','玄黑鎏金'],['cream','奶油暖白'],['red','朱红国风']].map(([k,v])=>`<option value="${k}" ${state.theme===k?'selected':''}>${v}</option>`).join('')}</select></div></div></div>`)}${card('节日限定',`<div class="row between"><span class="tiny">随节日自动换装，也可提前预览</span>${btn('主题预览','festival-preview')}</div>`)}${foldCard('手机使用与下载',`<p class="muted">${native?'APK内置同一套PWA业务模块，并保留安卓原生桌面组件。':'iPhone使用Safari，安卓使用Chrome：从浏览器菜单添加到主屏幕。无需注册应用账号。'}</p>${btn(native?'添加桌面小组件 / 原生专业工具':'查看主屏幕使用说明','install','full')}<a class="btn full" href="./download.html">安卓安装包 / 产品下载页</a><p class="tiny">网页版主屏幕图标不是原生安装包，也不能提供真正的 WidgetKit 桌面小组件。${ui.offline?'当前离线资源已就绪。':'离线缓存状态将在页面资源加载后检测。'}</p>`)}${foldCard('隐私和本机数据',`<p class="muted">出生档案、转盘、签文仅存当前浏览器本机，不会上传。更换浏览器、清理网站资料或 Safari 的主屏幕独立存储可能导致资料不互通，重要资料请先导出。</p><div class="row">${btn('导出本机资料','export')}${btn('导入备份','import')}${btn('清空资料','reset','danger')}</div><details class="faq"><summary>排盘采用什么规则？</summary><p>公历生日；北京时间 UTC+8；未校正真太阳时。年柱以立春、月柱按节气划分，晚子时采用流派2（日柱按当天）。未知时分以中午参考三柱，节气交界日需补时分复核。同一出生时间可能得到相同八字，不宣称全球唯一。</p></details><details class="faq"><summary>能预测人生、天气或实时方位吗？</summary><p>不能。抽签、分数和幸运元素均为娱乐，实时罗盘需主动授权并由设备支持，未启用时为固定方位图；网页版不提供原生通知或系统桌面组件；安卓 APK 保留原生桌面组件。</p></details><p class="tiny">历法：6tail / lunar-javascript · MIT许可<br>应用不收集出生资料，无广告。公开访问，无需登录；托管平台可能提供安全防护脚本。</p>`)}`;}
function isStandalone(){return window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
function icon(n){const paths=['M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7','M4 5h16v16H4zM4 10h16M8 3v4M16 3v4M8 14h2M14 14h2M8 17h2','M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M16 8l-2 6-6 2 2-6z','M7 9v12h10V9M5 9h14M8 9 6 3M11 9l1-7M15 9l3-6','M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2'];return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]}"/></svg>`;}
function render(scroll=true){document.body.dataset.theme=state.theme;document.body.dataset.page=['home','almanac','compass','sign','mine'][ui.tab];document.body.dataset.festival=ui.festivalPreview||festivalInfo(ui.date).theme?.id||'';const meta=document.querySelector('meta[name="theme-color"]');meta.content=state.theme==='cream'?'#f5f0e6':state.theme==='red'?'#210f15':'#101216';const last=window.scrollY;app.innerHTML=`<div class="wrap"><header class="topbar"><div><h1>神的日历</h1><small>国风生活 / V3.0.1 · 每日吉位</small></div><button class="icon-btn" data-action="install" aria-label="添加到主屏幕说明">↗</button></header>${storageIssue?`<div class="notice">${e(storageIssue)}</div>`:''}<main id="main">${[home,calendarPage,compassPage,signPage,myPage][ui.tab]()}</main><footer class="tiny" style="text-align:center;padding:15px 0"><span class="status-dot"></span>${ui.offline?'离线资源已就绪':'本机保存 · 真实历法'} · 趣味内容仅供娱乐</footer></div><nav class="bottom" aria-label="主要入口">${['首页','黄历','罗盘','抽签','我的'].map((v,i)=>`<button type="button" data-action="nav" data-tab="${i}" class="${ui.tab===i?'active':''}" ${ui.tab===i?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span><span>${v}</span></button>`).join('')}</nav>`;paintCompass();if(scroll)window.scrollTo(0,0);else window.scrollTo(0,last);}
function installGuide(){if(native){modal('安卓桌面与专业工具',`<p>当前APK内置与网页版相同的界面和业务模块，安装后即可离线使用。</p>${btn('添加原生桌面组件','native-widget','primary full')}${btn('打开保留的原生专业工具','native-tools','full')}<p class="tiny">桌面组件取决于安卓启动器支持，网页不会伪装成原生组件。</p>${closeButton()}`);return;}const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),android=/Android/i.test(navigator.userAgent);const steps=ios?'<li>用Safari打开当前正式网址。</li><li>点击分享按钮（方框向上箭头）。</li><li>选择“添加到主屏幕”，再点“添加”。</li>':android?'<li>用Chrome打开当前正式网址。</li><li>点击右上角⋮菜单。</li><li>选择“添加到主屏幕”或“安装应用”。</li>':'<li>用支持PWA的Chrome或Edge打开当前网址。</li><li>使用地址栏的安装图标或浏览器菜单中的安装选项。</li>';modal('添加到主屏幕',`<div class="notice">${isStandalone()?'当前已处于独立窗口模式。':ios?'iPhone / Safari 使用方法':android?'安卓 / Chrome 使用方法':'电脑浏览器安装说明'}</div><ol class="install-steps">${steps}</ol>${installPrompt?btn('安装到这台设备','browser-install','primary full'):''}<p class="muted">同一个HTTPS网址，免登录。第一次请保持联网，出现“离线资源已就绪”后支持缓存内的基础离线功能。</p><p class="tiny">主屏幕PWA不是原生iOS安装包，不提供WidgetKit。Safari、主屏幕和安卓APK的本地存储各自独立，跨设备可用本机备份导入导出，尚无云同步。</p>${closeButton()}`);}

function chooseIdentity(){modal('选择你的生活主题',`<div class="chips">${IDENTITIES.map((x,i)=>`<button class="chip ${state.identity===i?'active':''}" data-action="set-identity" data-index="${i}">${x}</button>`).join('')}</div><p class="muted">趣味建议采用本地模板，不上传资料，也不是科学预测。</p>${closeButton()}`);}
function editCustom(){modal('定制你的生活主题',`<form id="custom-form"><label for="custom-role">职业 / 身份</label><input id="custom-role" maxlength="24" value="${e(state.role)}" placeholder="例如：建筑学生"><label for="custom-interest">兴趣</label><input id="custom-interest" maxlength="32" value="${e(state.interest)}" placeholder="例如：摄影、旅行"><label for="custom-goal">近期目标</label><input id="custom-goal" maxlength="48" value="${e(state.goal)}" placeholder="例如：完成毕业设计"><button class="btn primary full" type="submit">保存生活主题</button></form>${closeButton()}`);document.querySelector('#custom-form').onsubmit=event=>{event.preventDefault();state.role=document.querySelector('#custom-role').value.trim();state.interest=document.querySelector('#custom-interest').value.trim();state.goal=document.querySelector('#custom-goal').value.trim();save();closeModal();render(false);};}
function editProfile(){const p=state.profile;modal(p?'修改个人出生档案':'建立个人出生档案',`<form id="profile-form"><label for="birth-name">昵称（最多12字）</label><input id="birth-name" maxlength="12" value="${e(p?.name||'')}" placeholder="给你的命盘起个名字" autocomplete="off"><label for="birth-date">出生公历日期</label><input id="birth-date" type="date" required min="1900-01-01" max="2100-12-31" value="${e(p?.date||'2000-01-01')}"><label class="check"><input type="checkbox" id="birth-known" ${p?.known?'checked':''}>出生时分已知（北京时间）</label><div id="birth-time-area" class="${p?.known?'':'hidden'}"><label for="birth-time">北京时间时分</label><input type="time" id="birth-time" value="${e(p?.time||'12:00')}"></div><p class="tiny">不知道时分可以留空，不编造时柱。全部资料只保存到当前浏览器本机。</p><p class="tiny" id="birth-error" role="alert"></p><button type="submit" class="btn primary full">生成我的命盘</button></form>${closeButton()}`);document.querySelector('#birth-known').onchange=event=>document.querySelector('#birth-time-area').classList.toggle('hidden',!event.target.checked);document.querySelector('#profile-form').onsubmit=event=>{event.preventDefault();try{const p={id:state.profile?.id||crypto.randomUUID(),name:document.querySelector('#birth-name').value.trim()||'我的',date:document.querySelector('#birth-date').value,known:document.querySelector('#birth-known').checked,time:document.querySelector('#birth-time').value};chartFor(p);state.profile=p;const ok=save();closeModal();ui.tab=4;render();toast(ok?'个人命盘已保存在本机':'命盘已生成，但本机保存失败，请导出备份');}catch(error){document.querySelector('#birth-error').textContent=error.message;}};}
function findDates(word){const s=dayInfo(ui.date).solar,rows=[];for(let n=0;n<60;n++){const d=s.next(n),l=d.getLunar();if(l.getDayYi().includes(word)&&!l.getDayJi().includes(word))rows.push(`${d.toYmd()}　星期${d.getWeekInChinese()}`);}modal('传统习俗宜日',`<p class="muted">从 ${ui.date} 起查未来60天 · ${e(word)}<br>仅匹配公共黄历，不是个人八字择日。</p><div class="muted">${rows.length?rows.map(e).join('<br>'):'未找到匹配日期。'}</div>${closeButton()}`);}
function editOptions(){let draft=[...state.options];const draw=()=>{modal('编辑转盘 · 每项等概率',`<form id="options-form"><p class="tiny">2—12个不同选项，每项最多16字。</p><div class="option-editor">${draft.map((v,i)=>`<div class="option-row"><span>${i+1}</span><input aria-label="选项${i+1}" data-opt="${i}" maxlength="32" value="${e(v)}"><button type="button" class="icon-btn" data-remove="${i}" aria-label="删除选项${i+1}">×</button></div>`).join('')}</div><button class="btn full" type="button" id="add-option" ${draft.length>=12?'disabled':''}>＋ 添加选项</button><p id="options-error" class="tiny" role="alert"></p><button class="btn primary full" type="submit">保存选项</button></form>${closeButton()}`);const collect=()=>{draft=[...dialog.querySelectorAll('[data-opt]')].map(el=>el.value);};dialog.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{collect();if(draft.length<=2){toast('至少保留两个选项');return;}draft.splice(Number(el.dataset.remove),1);draw();});dialog.querySelector('#add-option').onclick=()=>{collect();draft.push('');draw();dialog.querySelector('[data-opt="'+(draft.length-1)+'"]').focus();};dialog.querySelector('#options-form').onsubmit=event=>{event.preventDefault();try{collect();if(draft.some(x=>!x.trim()))throw Error('请填写每个选项，或删除空选项');state.options=parseOptions(draft.join('\n'));save();ui.rotation=0;ui.result='';closeModal();render(false);}catch(error){dialog.querySelector('#options-error').textContent=error.message;}};};draw();}
function saveWheel(){modal('收藏当前转盘',`<form id="save-wheel-form"><label for="wheel-name">转盘名称</label><input id="wheel-name" maxlength="24" required placeholder="例如：周末去哪玩"><button type="submit" class="btn primary full">收藏</button></form>${closeButton()}`);document.querySelector('#save-wheel-form').onsubmit=event=>{event.preventDefault();const name=document.querySelector('#wheel-name').value.trim();if(!name)return;state.wheels.push({id:crypto.randomUUID(),name,options:[...state.options]});save();closeModal();render(false);toast('已收藏转盘');};}
function sound(final=false){if(native){native.feedback(!!state.sound,final&&!!state.vibrate);return;}if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const context=new C();const osc=context.createOscillator(),gain=context.createGain();osc.frequency.value=660;gain.gain.value=.035;osc.connect(gain);gain.connect(context.destination);osc.start();gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+.15);osc.stop(context.currentTime+.17);osc.onended=()=>context.close();}catch{}}
function spinWheel(){if(ui.spinning)return;const opts=[...state.options],i=randomIndex(opts.length);ui.spinning=true;ui.result='';const start=ui.rotation,norm=((start%360)+360)%360,target=start+2160+(landing(i,opts.length)-norm+360)%360,disc=document.querySelector('#wheel-disc');document.querySelector('#wheel-result').textContent='转动中…';document.querySelectorAll('[data-action="spin"]').forEach(b=>b.disabled=true);const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,begin=performance.now(),duration=reduced?100:3800;disc.style.transition='none';sound();function frame(now){const t=Math.min(1,(now-begin)/duration),angle=start+(target-start)*wheelProgress(t);disc.style.transform=`rotate(${angle}deg)`;if(t<1){requestAnimationFrame(frame);return;}ui.rotation=target;ui.result=opts[pointer(target,opts.length)];ui.spinning=false;if(!native&&state.vibrate&&navigator.vibrate)navigator.vibrate(45);sound(true);render(false);modal('今天就选这个！',`<div class="result-reveal"><span>随机决定 / 每项等概率</span><strong>${e(ui.result)}</strong><p>小决定有答案，接下来就出发。</p></div>${btn('生成结果海报','share-wheel','primary full')}${closeButton()}`);}requestAnimationFrame(frame);}
function drawSign(){if(ui.signBusy)return;ui.signBusy=true;const date=dateKey(),type=ui.type;render(false);setTimeout(()=>{if(!state.signs.find(x=>x.day===date&&x.type===type)){state.signs.push({id:date+'_'+type,day:date,type,...dailySign(type,date,state.id),favorite:false});save();}ui.signBusy=false;sound(true);render(false);},850);}
function history(){const rows=[...state.signs].sort((a,b)=>b.day.localeCompare(a.day)||a.type-b.type);modal('签文历史与收藏',rows.length?rows.map(r=>`<div class="saved-row" style="display:block"><p class="tiny">${e(r.day)} · ${SIGN_TYPES[r.type]} · ${e(r.grade)}〔娱乐〕</p><p>${e(r.text)}</p><p class="muted">行动：${e(r.task)}</p><button class="chip ${r.favorite?'active':''}" data-action="favorite-history" data-id="${e(r.id)}">${r.favorite?'★ 已收藏':'☆ 收藏'}</button></div>`).join('')+closeButton():'<p class="muted">还没有抽签记录。</p>'+closeButton());}
function dictionary(word){const d={日主:'出生日的天干，是八字关系的参照点。',正财:'日主所克、阴阳相异的传统关系名称，不是收入保证。',偏财:'日主所克、阴阳相同的传统关系名称，不代表偏门发财。',七杀:'克制日主且同阴阳的关系名称，不代表现实灾祸。',正官:'克制日主且阴阳相异的天干关系。',正印:'生助日主且阴阳相异的天干关系。',偏印:'生助日主且同阴阳的天干关系。',食神:'日主所生且同阴阳的天干关系。',伤官:'日主所生且阴阳相异的关系，不是伤害他人的意思。',比肩:'同五行、同阴阳的天干关系。',劫财:'同五行、异阴阳的传统关系，不代表被抢钱。',桃花:'传统神煞术语；这里的桃花签只是娱乐，未计算个人桃花神煞。',纳音:'六十甲子的传统分类名称，不等同于日主五行。',命宫:'依传统月时算法排出的宫位参考，不是人生预测的证明。'};if(word&&d[word]){modal(word+' · 简明解释',`<p>${e(d[word])}</p>${closeButton()}`);return;}modal('术语小词典',Object.entries(d).map(([w,t])=>`<details class="faq"><summary>${w}</summary><p>${t}</p></details>`).join('')+closeButton());}
function speechStatus(text){const el=document.querySelector('#speech-status');if(el)el.textContent=text;const syn=window.speechSynthesis;for(const [action,active] of [['speech-pause',syn?.speaking&&!syn?.paused],['speech-resume',syn?.paused],['speech-stop',syn?.speaking||syn?.paused]]){const b=document.querySelector('[data-action="'+action+'"]');if(b)b.disabled=!active;}}
function speak(){const b=profileChart();if(!b)return;if(native){native.speak(chartReading(b));return;}if(!('speechSynthesis'in window)){toast('当前浏览器不支持语音朗读');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(chartReading(b));u.lang='zh-CN';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('zh'));if(voice)u.voice=voice;u.onstart=()=>speechStatus('正在朗读');u.onend=()=>setTimeout(()=>speechStatus('朗读结束'),0);u.onerror=()=>toast('中文语音暂不可用，请检查系统语音设置');speechSynthesis.speak(u);}
function exportData(){modal('导出本机备份',`<p class="muted">默认导出设置、转盘和签文，不包含出生档案。文件可手动导入 Safari 或主屏幕网页版。</p><label class="check"><input type="checkbox" id="include-birth">明确包含出生档案（文件含敏感资料）</label>${btn('生成备份文件','download-backup','primary full')}${blocked?btn('导出无法读取的原资料','download-raw','full'):''}${closeButton()}`);}
function download(text,name,type='application/json'){if(native){native.saveText(text,name);return;}const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function importData(){modal('从本机备份恢复',`<p class="muted">导入会替换当前资料，建议先导出。只接受本应用格式的JSON备份，文件不会上传服务器。</p><input type="file" id="backup-input" accept="application/json,.json"><p class="tiny" id="import-error" role="alert"></p>${closeButton()}`);document.querySelector('#backup-input').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>3e6)throw Error('文件过大，请选择本应用的备份文件');const imported=validateState(JSON.parse(await file.text()));modal('确认恢复备份',`<p>将恢复 ${imported.wheels.length} 个转盘、${imported.signs.length} 条签文${imported.profile?'和出生档案':''}，并替换当前资料。</p>${btn('确认恢复','confirm-import','primary full')}${closeButton()}`);document.querySelector('[data-action="confirm-import"]').onclick=()=>{state=imported;ui.result='';ui.rotation=0;blocked=false;storageIssue='';save();closeModal();render();toast('已恢复到本机');};}catch(error){document.querySelector('#import-error').textContent=error.message;}};}
async function makePoster(title,lines){const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const c=canvas.getContext('2d');const gradient=c.createLinearGradient(0,0,1080,1920);gradient.addColorStop(0,'#29231c');gradient.addColorStop(1,'#0f131a');c.fillStyle=gradient;c.fillRect(0,0,1080,1920);c.strokeStyle=gold;c.lineWidth=2;c.beginPath();roundRect(c,34,34,1012,1852,32);c.stroke();c.fillStyle=gold;c.font='32px -apple-system,"PingFang SC",sans-serif';c.fillText('中 华 万 年 黄 历  /  青春国风',80,112);c.font='58px -apple-system,"PingFang SC",sans-serif';c.fillText(title,80,224);c.font='28px -apple-system,"PingFang SC",sans-serif';c.fillText(dateKey(),80,292);c.font='36px -apple-system,"PingFang SC",sans-serif';c.fillStyle='#f0e6d4';let y=378;for(const text of lines){const split=wrapCanvas(c,text,890);for(const line of split){if(y>1450)break;c.fillText(line,80,y);y+=55;}y+=20;if(y>1450)break;}c.save();c.strokeStyle='#55482e';c.lineWidth=2;for(const r of [125,114]){c.beginPath();c.arc(540,1325,r,0,Math.PI*2);c.stroke();}c.fillStyle='#a28b58';c.font='74px serif';c.fillText('知 时',435,1348);c.restore();try{const img=await loadImage('./visit-qr.png');c.fillStyle='#fff';c.fillRect(784,1570,220,220);c.drawImage(img,784,1570,220,220);c.font='20px -apple-system,"PingFang SC",sans-serif';c.fillStyle=gold;c.fillText('扫码下载 / 网页体验',784,1828);}catch{}c.fillStyle='#b1a28b';c.font='24px -apple-system,"PingFang SC",sans-serif';c.fillText('传统文化 / 趣味内容仅供娱乐',80,1680);c.fillText('默认隐藏姓名、生日与个人命盘',80,1725);c.font='18px -apple-system,"PingFang SC",sans-serif';c.fillText('日有所知，心有所向 · 神的日历',80,1810);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('图片生成失败，请重试');if(posterURL)URL.revokeObjectURL(posterURL);posterURL=URL.createObjectURL(blob);posterFile=new File([blob],`almanac-${dateKey()}.png`,{type:'image/png'});modal('国风分享海报',`<p class="tiny">已生成1080×1920竖版PNG。可用系统分享菜单；微信、抖音是否出现取决于手机与平台支持，也可保存后上传。出生档案默认不参与分享。自定义目标和选项如含私人文字，请自行确认。</p><img class="poster-preview" src="${posterURL}" alt="国风分享海报">${btn('分享图片','native-share','primary full')}${native?btn('保存图片到手机','native-save-poster','full'):`<a class="btn full" href="${posterURL}" download="almanac-${dateKey()}.png">保存图片</a>`}${native?'':`<a class="btn full" href="${posterURL}" target="_blank" rel="noopener">打开图片（iPhone可长按存储）</a>`}${closeButton()}`);}
function roundRect(c,x,y,w,h,r){c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}
function wrapCanvas(c,text,width){const result=[];for(const paragraph of String(text).split('\n')){let line='';for(const char of paragraph){if(c.measureText(line+char).width>width){result.push(line);line=char;}else line+=char;}result.push(line);}return result;}
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});}
async function share(title,lines){try{await makePoster(title,lines);}catch(error){toast(error.message);}}
document.addEventListener('click',async event=>{const node=event.target.closest('[data-action]');if(!node)return;const a=node.dataset.action;if((ui.spinning||ui.signBusy)&&!['close'].includes(a)){toast('请稍候，当前动画即将揭晓');return;}try{switch(a){case'compass-toggle':if(liveCompass.snapshot().active)liveCompass.stop();else await liveCompass.start();break;case'open-wheel':liveCompass.stop();ui.tab=2;ui.compassMode=1;render();break;case'compass-mode':if(Number(node.dataset.mode)===1)liveCompass.stop();ui.compassMode=Number(node.dataset.mode);render(false);break;case'festival-preview':festivalPreview();break;case'festival-set':ui.festivalPreview=node.dataset.id;ui.tab=0;closeModal();render();break;case'festival-reset':ui.festivalPreview='';closeModal();render(false);break;case'browser-install':if(installPrompt){const p=installPrompt;installPrompt=null;await p.prompt();closeModal();}break;case'native-widget':native?.pinWidget();break;case'native-tools':native?.openNative();break;case'native-save-poster':if(native&&posterFile){const reader=new FileReader();reader.onload=()=>native.savePNG(reader.result);reader.readAsDataURL(posterFile);}break;case'privacy':state.privacy=!state.privacy;save();render(false);break;case'speech-pause':if(native){native.speechControl('pause');break;}if('speechSynthesis'in window&&speechSynthesis.speaking){speechSynthesis.pause();speechStatus('已暂停');}break;case'speech-resume':if(native){native.speechControl('resume');break;}if('speechSynthesis'in window&&speechSynthesis.paused){speechSynthesis.resume();speechStatus('继续朗读');}break;case'speech-stop':if(native){native.speechControl('stop');break;}if('speechSynthesis'in window)speechSynthesis.cancel();setTimeout(()=>speechStatus('已停止'),0);break;case'share-theme':await share(idName()+' · 主题黄历',[task(),'趣味状态分 '+(60+stable(dateKey()+state.id+idName(),40))+' / 100〔娱乐〕','小小行动，也算今天的进度。']);break;case'term-group':{const words=JSON.parse(node.dataset.words);modal(words.join(' / ')+' · 传统原义',words.map(w=>`<p><strong>${e(w)}</strong>：${e(terms[w]||'传统习俗事项')}</p>`).join('')+`<p class="tiny">原始归类：${node.dataset.avoid==='1'?'忌':'宜'}。年轻化文案只作表达改编，不预测结果。</p>${closeButton()}`);break;}case'choose-direction':ui.direction=node.dataset.id;render(false);break;case'direction-help':{const d=dailyDirections(ui.date);modal('每日方位 · 传统含义',`<p>方位从北起顺时针：北0°、东90°、南180°、西270°。金色虚线标记所选吉神；启用实时方向后随盘转动。</p>${d.items.map(x=>`<p><strong>${x.name} · ${x.direction}</strong><br>${x.meaning}</p>`).join('')}<p class="tiny">煞向为传统日煞方位，与吉神分开显示。采用现有lunar历法库，福神使用第二流派；各流派可能不同。民俗文化参考，不是科学预测，不替代安全和现实判断。日期以页面所选日期为准，零时切日。</p>${closeButton()}`);break;}case'close':closeModal();break;case'nav':{const tab=Number(node.dataset.tab);if(tab===ui.tab)break;if(ui.tab===2&&tab!==2)liveCompass.stop();ui.tab=tab;if('speechSynthesis'in window)speechSynthesis.cancel();render();break;}case'install':installGuide();break;case'identity':chooseIdentity();break;case'set-identity':state.identity=Number(node.dataset.index);save();closeModal();render(false);if(state.identity===5)editCustom();break;case'custom-identity':editCustom();break;case'part':ui.part=Number(node.dataset.part);render();break;case'language':state.traditional=!state.traditional;save();render(false);break;case'today':ui.date=dateKey();render(false);break;case'select-date':ui.date=node.dataset.date;render(false);break;case'month-prev':case'month-next':{const[y,m]=dateParts(ui.date),d=new Date(y,m-1+(a==='month-prev'?-1:1),1,12);if(d.getFullYear()<1900||d.getFullYear()>2100)break;ui.date=dateKey(d);render(false);break;}case'term':{const w=node.dataset.word;modal(w+' · 传统原义',`<p>${e(terms[w]||'传统历法术语')}</p><p class="muted">原始归类：${node.dataset.avoid==='1'?'忌':'宜'} · ${e(category(w))}<br>年轻文案只改写表达，不更改真实黄历。</p>${closeButton()}`);break;}case'find-dates':findDates(node.dataset.word);break;case'mountain':{const n=Number(node.dataset.index),words=['子','癸','丑','艮','寅','甲','卯','乙','辰','巽','巳','丙','午','丁','未','坤','申','庚','酉','辛','戌','乾','亥','壬'];modal(words[n]+' · '+n*15+'°',`<p>这是从北向顺时针量取的中心方位；二十四山每格15°。</p><p class="muted">此盘用于了解传统方位；仅在启用实时罗盘并取得数据时读取手机朝向。戊己在中央，不放在外圈。</p>${closeButton()}`);break;}case'edit-profile':editProfile();break;case'delete-profile':modal('删除本机出生档案？',`<p>出生资料和个人命盘将从当前浏览器删除，转盘与签文保留。</p>${btn('确认删除出生档案','confirm-delete-profile','danger full')}${closeButton()}`);break;case'confirm-delete-profile':state.profile=null;save();closeModal();render(false);break;case'pillar':{const b=profileChart(),i=Number(node.dataset.index);modal(['年柱','月柱','日柱','时柱'][i]+' · '+b.pillars[i],`<p>四柱分别用天干地支表示出生的年、月、日、时。年柱以立春、月柱按节气分界。</p><p>天干十神：${e(b.tenGods[i])}<br>纳音：${e(b.nayin[i])}</p><p class="muted">十神是其他天干与日干的传统关系名称，不是现实的神明或命运结论。</p>${btn('打开术语小词典','dictionary','full')}${closeButton()}`);break;}case'dict-term':dictionary(node.dataset.word);break;case'dictionary':dictionary();break;case'speak':speak();break;case'edit-options':editOptions();break;case'save-wheel':saveWheel();break;case'template':state.options=[['火锅','面条','轻食','食堂'],['公园','书店','咖啡馆','博物馆'],['我请','你请','各付各的'],['学习','运动','收拾房间','先休息']][Number(node.dataset.template)];ui.result='';ui.rotation=0;save();render(false);break;case'load-wheel':state.options=[...state.wheels[Number(node.dataset.index)].options];ui.result='';ui.rotation=0;save();render(false);break;case'delete-wheel':state.wheels.splice(Number(node.dataset.index),1);save();render(false);break;case'spin':spinWheel();break;case'sign-type':ui.type=Number(node.dataset.type);render(false);break;case'draw':drawSign();break;case'favorite':{const r=recordFor();if(r){r.favorite=!r.favorite;save();render(false);toast(r.favorite?'已收藏':'已取消收藏');}break;}case'history':history();break;case'favorite-history':{const r=state.signs.find(x=>x.id===node.dataset.id);if(r){r.favorite=!r.favorite;save();history();}break;}case'share-day':{const d=dayInfo(ui.date);await share('今日国风生活',[d.lunar+' · '+d.weekday,'宜 · '+groupTerms(d.yi,terms,state.style).slice(0,4).map(v=>v.label).join(' / '),'忌 · '+groupTerms(d.ji,terms,state.style).slice(0,4).map(v=>v.label).join(' / '),ui.tab===0?idName()+'：'+task():'传统文化参考，生活由你决定。']);break;}case'share-wheel':if(ui.result)await share('随机决定',['抽中了：'+ui.result,'参与选项：'+state.options.join(' · '),'每项等概率，仅供日常小决定参考。']);break;case'share-sign':{const r=recordFor();if(r)await share(SIGN_TYPES[r.type],[r.grade+'〔娱乐〕',r.text,'行动：'+r.task]);break;}case'native-share':if(native&&posterFile){const reader=new FileReader();reader.onload=()=>native.sharePNG(reader.result);reader.readAsDataURL(posterFile);break;}if(posterFile&&navigator.canShare?.({files:[posterFile]})){try{await navigator.share({files:[posterFile],title:'神的日历 · 青春国风'});}catch(error){if(error.name!=='AbortError')toast('分享暂不可用，请保存图片或长按存储');}}else toast('当前浏览器不支持文件分享，请保存图片或打开后长按存储');break;case'export':exportData();break;case'download-backup':{const data=structuredClone(state);if(!document.querySelector('#include-birth').checked)data.profile=null;download(JSON.stringify(data,null,2),`almanac-backup-${dateKey()}.json`);toast('已生成本机备份文件');break;}case'download-raw':download(localStorage.getItem(KEY)||'',`almanac-original-${dateKey()}.json`);break;case'import':importData();break;case'reset':modal('清空当前浏览器资料？',`<p>此操作删除出生档案、转盘、签文与偏好设置，无法撤销。请先导出备份。</p>${btn('确认清空全部本机资料','confirm-reset','danger full')}${closeButton()}`);break;case'confirm-reset':state=defaultState();state.intro=true;blocked=false;storageIssue='';save();ui.result='';ui.rotation=0;closeModal();render();toast('已清空当前浏览器资料');break;}}catch(error){toast(error.message||'操作失败，请重试');}});
document.addEventListener('change',event=>{try{switch(event.target.id){case'query-date':dateParts(event.target.value);ui.date=event.target.value;render(false);break;case'category':ui.filter=event.target.value;render(false);break;case'identity-select':state.identity=Number(event.target.value);save();render(false);if(state.identity===5)editCustom();break;case'style-select':state.style=Number(event.target.value);save();render(false);break;case'theme-select':state.theme=event.target.value;save();render(false);break;case'reading-select':state.reading=Number(event.target.value);save();render(false);break;case'native-shake':state.shake=event.target.checked;save();break;case'vibrate':state.vibrate=event.target.checked;save();break;case'sound':state.sound=event.target.checked;save();break;}}catch(error){toast(error.message);}});
document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('svg [role=button]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
function intro(){modal('把日常过得有点国风',`<p class="quote">知时而行，也留从容。</p><p>查真实黄历、建立个人命盘、转一个小决定、抽一句鼓励。无需注册应用账号，出生资料只存在当前浏览器。</p><p class="muted">公开访问，无需登录。抽签、分数与幸运元素均为娱乐。主屏幕网页版不是原生安装包。</p>${btn('开启今天','close','primary full')}`);state.intro=true;save();}
render();if(!state.intro)setTimeout(intro,250);
async function prepareOffline(){if(native){ui.offline=true;const foot=document.querySelector('footer');if(foot)foot.innerHTML='APK内置离线资源 · 与网页版共用业务模块';return;}if(!('serviceWorker'in navigator))return;try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;const worker=registration.active||navigator.serviceWorker.controller;if(!worker)return;const channel=new MessageChannel();channel.port1.onmessage=event=>{ui.offline=event.data===true;if(ui.offline){const foot=document.querySelector('footer');if(foot)foot.innerHTML='<span class="status-dot"></span>离线资源已就绪 · 趣味内容仅供娱乐';}};worker.postMessage('CACHE_READY',[channel.port2]);}catch{ui.offline=false;}}
prepareOffline();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!ui.spinning&&!ui.signBusy&&ui.tab===0)render(false);});

let lastCalendarDay=dateKey();setInterval(()=>{const current=dateKey();if(current!==lastCalendarDay&&!ui.spinning&&!ui.signBusy&&!dialog.open){const wasToday=ui.date===lastCalendarDay;lastCalendarDay=current;if(wasToday)ui.date=current;render(false);}},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&lastCalendarDay!==dateKey()&&!ui.spinning&&!ui.signBusy&&!dialog.open){lastCalendarDay=dateKey();render(false);}});

window.AlmanacShake=()=>{if(ui.tab===2&&ui.compassMode===1&&!ui.spinning&&!ui.signBusy&&!dialog.open)spinWheel();};
window.AlmanacSpeechStatus=text=>{speechStatus(text);for(const action of ['speech-pause','speech-resume','speech-stop']){const b=document.querySelector(`[data-action="${action}"]`);if(b)b.disabled=action==='speech-resume'?text!=='已暂停':!['正在朗读','已暂停'].includes(text);}};
window.AlmanacNativeResume=value=>{if(blocked||ui.spinning||ui.signBusy)return;try{if((value.updatedAt||0)<(state.updatedAt||0))return;if(JSON.stringify(state.options)!==JSON.stringify(value.options)){ui.rotation=0;ui.result='';}state=migrateState(value);localStorage.setItem(KEY,JSON.stringify(state));if(!ui.spinning&&!ui.signBusy)render(false);}catch{toast('原生资料暂未同步，当前网页资料已保留');}};
let installPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});

if(native&&(new URL(location.href).searchParams.has('profile')||window.__nativeOpenProfile)){ui.tab=4;render();}

document.addEventListener('visibilitychange',()=>{if(document.hidden&&(liveCompass.snapshot().active||liveCompass.snapshot().status==='requesting'))liveCompass.stop('后台已暂停方向读取 · 返回后请重新启用','paused');});
window.addEventListener('pagehide',()=>liveCompass.stop());

// Only the trusted bundled native bridge can invoke this callback.
window.AlmanacCompassSample=data=>window.dispatchEvent(new CustomEvent('almanaccompass',{detail:data}));

window.AlmanacCompassPaused=()=>liveCompass.stop("安卓方向读取已暂停 · 点击启用可重试","paused");
